<template><div class="builder"><div v-for="(rule,index) in modelValue" :key="index" class="rule"><el-select v-model="rule.source" filterable placeholder="响应字段" aria-label="选择响应字段"><el-option-group v-if="fields.length" label="响应字段"><el-option v-for="field in fields" :key="field" :label="field" :value="field"/></el-option-group><el-option label="HTTP 状态码" value="$status"/><el-option label="响应耗时" value="$elapsed"/></el-select><el-select v-model="rule.operator" aria-label="选择判断条件"><el-option v-for="item in ASSERT_OPERATORS" :key="item.value" :label="item.label" :value="item.value"/></el-select><el-input v-if="!['exists','not_exists'].includes(rule.operator)" v-model="rule.expected" placeholder="期望值" aria-label="期望值"/><el-button text type="danger" aria-label="删除断言" @click="remove(index)"><el-icon><Delete/></el-icon></el-button></div><el-button plain @click="add">添加断言</el-button></div></template>
<script setup lang="ts">import{Delete}from'@element-plus/icons-vue';import{ASSERT_OPERATORS}from'@/constants/options';export type AssertRule={source:string;operator:string;expected?:string|number|boolean};const props=withDefaults(defineProps<{modelValue:AssertRule[];fields?:string[]}>(),{fields:()=>[]});const emit=defineEmits<{(e:'update:modelValue',value:AssertRule[]):void}>();function add(){emit('update:modelValue',[...props.modelValue,{source:props.fields[0]||'$status',operator:'eq',expected:''}])}function remove(index:number){emit('update:modelValue',props.modelValue.filter((_,i)=>i!==index))}</script>
<style scoped>.builder{display:grid;gap:10px}.rule{display:grid;grid-template-columns:minmax(170px,1.2fr) 130px minmax(150px,1fr) 34px;gap:8px;align-items:center}@media(max-width:768px){.rule{grid-template-columns:1fr 1fr}.rule .el-input{grid-column:1 / -1}}</style>
